    source: `${course}/weeks/week2.html`,
    gaps: ['The weekly page was fully reviewed. Full textbook chapters and linked videos were not independently reviewed. Simulations in this companion are synthetic examples; reported Marvel benchmarks come from the frozen course dataset and primary page.'],
